// Opal Reader v2 candidate service worker (D5-C packaging build).
// Generated by packaged/tools/build-packaged.mjs from this template:
// the cache id and the shell asset list below are build-inlined.
//
// Discipline (design 4.5, as corrected by Rowan 6393935364 item A and
// Rowan 6399610651 item A):
// - Cache reads and writes are scoped to THIS candidate's cache only.
//   No global caches.match(...) anywhere: a global match can select
//   an entry from a retained v1/unknown cache, and with overlapping
//   document URLs a network failure could then serve an older or
//   mixed shell. Every lookup below opens CACHE by name.
// - The "ONLY this candidate's shell assets" policy is enforced, not
//   just stated: a request is intercepted ONLY if it is a navigation
//   or its path names an entry of the inlined SHELL list. Every other
//   same-origin GET (non-shell paths, API paths, audio) is left to
//   the browser untouched — never served from cache, never stored.
// - Network responses are stored ONLY when response.ok. An error
//   response never replaces a known-good cached asset: on a non-ok
//   network response or a network failure, a shell request is served
//   from this candidate's cache if a copy exists; an asset request
//   with no cached copy fails — it NEVER falls back to the HTML
//   document. The document fallback is for navigations only.
// - On activate this worker deletes NOTHING except the caches on the
//   explicit candidate-owned allowlist below (prior identities of
//   THIS packaging line). Every other cache — the entire v1 line
//   (opalreader-shell-v134…v207, including runtime-cached v1 audio),
//   the document-only d5b-* names, and anything unknown — is
//   preserved untouched, per the D5-C packet §1.3 retained-v1
//   guarantee: the candidate must never delete or clear v1 local
//   state or v1 caches. (The v1 worker's own prefix-purge discipline
//   is v1's business on v1's own activations; it is not imported
//   here.) Non-GET requests are never intercepted.
// - Request classification is SCOPE-RELATIVE (Rowan 6400157860):
//   request paths are resolved against this worker's registration
//   scope (the directory the script is served from), never compared
//   origin-absolute against the scope-relative SHELL entries. The
//   distinction is load-bearing in production: the app is a GitHub
//   Pages PROJECT site served under the "/opal-reader/" subpath
//   (Pages html_url https://jedavid33-design.github.io/opal-reader/,
//   cname null, no CNAME file — verified 2026-10-25), so a bundle
//   request's pathname there is "/opal-reader/app-259.js". The
//   previous origin-absolute comparison computed
//   "./opal-reader/app-259.js", matched nothing, and let every
//   non-navigation shell request bypass the worker entirely — the
//   offline precache would never have served them. Out-of-scope
//   URLs are rejected explicitly (never intercepted). Navigation
//   normalization is intentional and narrow: see
//   isNormalizableNavigation below.
const CACHE = "opalreader-shell-d5c3";
const SHELL = [
  "./",
  "./index.html",
  "./app-259.js",
  "./styles-150.css",
  "./manifest.webmanifest",
  "./icon.png",
  "./icon-192.png",
  "./icon-512.png",
  "./icon.svg",
  "./modules/audio-transport.js",
  "./modules/composition.js",
  "./modules/constants.js",
  "./modules/device-identity.js",
  "./modules/diagnostics.js",
  "./modules/entry.js",
  "./modules/lifecycle.js",
  "./modules/ownership.js",
  "./modules/player.js",
  "./modules/position-reporter.js",
  "./modules/runnable.js",
  "./modules/screens.js",
  "./modules/storage-adapter.js",
  "./modules/vendor/client/assembled-client.js",
  "./modules/vendor/client/funnel.js",
  "./modules/vendor/client/http-transport.js",
  "./modules/vendor/client/projection.js",
  "./modules/vendor/client/removals.js",
  "./modules/vendor/client/shelf-bridge.js",
  "./modules/vendor/client/surfaces.js",
  "./modules/vendor/client-store.js"
];
// Prior candidate-owned cache identities this worker may clean up:
// opalreader-shell-d5c1 was the first packaging build's cache id
// (never published); opalreader-shell-d5c2 was the d5c-pkg-2…pkg-6
// packaging generation's cache id (also never published), retired
// by the d5c-pkg-7 rename (packet draft v6 §4.4). This worker's own
// cache is created fresh and is never on the list. NOTHING else is
// ever deleted by this worker.
const PURGE_ON_ACTIVATE = ["opalreader-shell-d5c1", "opalreader-shell-d5c2"];

const SHELL_KEYS = new Set(SHELL);
// The path of a same-origin URL relative to this worker's
// registration scope (the directory the script is served from; the
// shell registers ./sw-d5c3.js with no scope override, so the scope
// IS that directory), or null when the URL lies outside the scope.
// The scope root requested without its trailing slash ("/opal-reader"
// for the production project path) names the scope root itself.
function scopeRelativePath(url) {
  const scopePath = new URL(self.registration.scope).pathname; // always ends with "/"
  if (url.pathname === scopePath.slice(0, -1)) return "";
  if (!url.pathname.startsWith(scopePath)) return null; // out of scope: explicit rejection
  return url.pathname.slice(scopePath.length);
}
// The cache key a same-origin request URL maps to, or null when the
// request is outside the scope or not one of this candidate's shell
// assets. Query strings (the ?v= build markers on the document's own
// pointers) do not change which asset a path names; cache lookups use
// ignoreSearch so a versioned request still finds the precached entry.
function shellKey(url) {
  const rel = scopeRelativePath(url);
  if (rel === null) return null;
  if (rel === "") return "./";
  const key = "./" + rel;
  return SHELL_KEYS.has(key) ? key : null;
}
// Navigation normalization is intentional and narrow. The shell
// declares NO path deep links: its screens are DOM state and the
// bundle performs no history/hash routing, so the only navigations
// this worker normalizes are the scope root and its index document.
// Any other in-scope navigation path is left to the browser
// untouched — it is never answered with the shell document.
function isNormalizableNavigation(url) {
  const rel = scopeRelativePath(url);
  return rel === "" || rel === "index.html";
}

self.addEventListener("install", (e) =>
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting())),
);
self.addEventListener("activate", (e) =>
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((key) => PURGE_ON_ACTIVATE.includes(key)).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  ),
);
self.addEventListener("fetch", (e) => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url);
  if (url.origin !== location.origin) return; // cross-origin (worker API, audio) bypasses entirely
  const rel = scopeRelativePath(url);
  if (rel === null) return; // outside this worker's scope: never intercepted
  if (rel.startsWith("v2/")) return; // API paths are never served from or written to cache
  if (rel.includes("sync/audio/")) return; // audio bytes are never cached by the shell worker

  const navigation = e.request.mode === "navigate";
  if (navigation && !isNormalizableNavigation(url)) return; // only the scope root / its document are normalized
  const key = shellKey(url);
  if (!navigation && key === null) return; // not a shell asset: not intercepted, never cached

  const cacheFirst =
    !navigation && key !== null && !/\.(?:js|css)$/.test(key) && !url.searchParams.has("v");

  e.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      if (cacheFirst) {
        const hit = await cache.match(e.request, { ignoreSearch: true });
        if (hit) return hit;
      }
      let response = null;
      let networkError = null;
      try {
        response = await fetch(e.request);
      } catch (err) {
        networkError = err;
      }
      if (response && response.ok) {
        // Only known-good responses are stored, and only in this
        // candidate's own cache.
        await cache.put(e.request, response.clone());
        return response;
      }
      // Network failed or answered non-ok: fall back to THIS
      // candidate's cache only. Navigations may fall back to the
      // shell document; asset requests may not — a failed JS/CSS
      // fetch must never be answered with the HTML document.
      const hit = await cache.match(e.request, { ignoreSearch: true });
      if (hit) return hit;
      if (navigation) {
        // The precached shell document lives at the scope root URL
        // (the "./" entry, resolved against the script's directory).
        const doc = await cache.match(self.registration.scope, { ignoreSearch: true });
        if (doc) return doc;
      }
      if (response) return response; // the non-ok response itself; it was not cached
      throw networkError; // genuine network failure with no cached copy: the request fails
    })(),
  );
});
